<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class SeoMonthlyCycle extends Model {protected $fillable=['seo_campaign_id','month','objectives','status','created_by'];protected $casts=['month'=>'date'];public function campaign(){return $this->belongsTo(SeoCampaign::class,'seo_campaign_id');}public function activities(){return $this->hasMany(SeoActivity::class);}}
